75	    const size_t elems = (size_t)NEON_ROT_LDR_AT_TOP_ROWMAJOR_SVE_SLOTS * lanes;
76	
77	    auto *data = static_cast<NeonRotLdrAtTopRowMajorSveData *>(malloc(sizeof(NeonRotLdrAtTopRowMajorSveData)));
78	    data->lanes = lanes;
79	    data->srcA = static_cast<uint64_t *>(aligned_alloc(64, elems * sizeof(uint64_t)));
80	    data->srcB = static_cast<uint64_t *>(aligned_alloc(64, elems * sizeof(uint64_t)));
81	    data->scratch = static_cast<uint64_t *>(aligned_alloc(64, elems * sizeof(uint64_t)));
82	    data->expected = static_cast<uint64_t *>(aligned_alloc(64, elems * sizeof(uint64_t)));
83	
