95	            case 0: res = svadd_u64_x(pg, a, b); break;
96	            case 1: res = sveor_u64_x(pg, a, b); break;
97	            case 2: res = svand_u64_x(pg, a, b); break;
98	            case 3: res = svorr_u64_x(pg, a, b); break;
