import re, difflib

def load(path):
    insns = {}
    for line in open(path):
        m = re.match(r'^\s*([0-9a-f]+):\t([0-9a-f ]+)\t(.*)$', line)
        if m:
            addr = int(m.group(1), 16)
            text = re.sub(r'\s*<[^>]*>.*$', '', m.group(3).rstrip())
            insns[addr] = text
    return insns

def norm(t):
    # normalize branch absolute targets to a placeholder
    return re.sub(r'^(b\.\w+|b|cbz|cbnz|tbz|tbnz)\s+\S+(.*)$', r'\1 T\2', t)

def seq(insns, lo, hi):
    return [norm(insns[a]) for a in sorted(insns) if lo <= a <= hi]

